<?= $this->include('operateur/partials/header', ['title' => 'Reglements operateurs']) ?>
<div class="mb-4"><h1 class="h3 mb-1">Situation des reglements operateurs</h1><p class="text-muted mb-0">Montants nets a envoyer ou a recevoir pour chaque operateur.</p></div>
<div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0 align-middle"><thead class="table-light"><tr><th>Operateur</th><th class="text-end">Solde de reglement</th><th class="text-end">Montant a envoyer</th><th class="text-end">Montant a recevoir</th></tr></thead><tbody><?php foreach ($comptes as $compte) : ?><tr><td><?= esc($compte['operateur_nom']) ?></td><td class="text-end"><?= number_format((float) $compte['solde'], 0, ',', ' ') ?> Ar</td><td class="text-end text-danger"><?= number_format(max((float) $compte['solde'], 0), 0, ',', ' ') ?> Ar</td><td class="text-end text-success"><?= number_format(max(-(float) $compte['solde'], 0), 0, ',', ' ') ?> Ar</td></tr><?php endforeach; ?><?php if (empty($comptes)) : ?><tr><td colspan="4" class="text-center text-muted py-4">Aucun compte operateur.</td></tr><?php endif; ?></tbody></table></div></div>
